package assets

import "encoding/base64"

// JPEG payloads embedded as base64 so the repo can be pushed without binary blobs via text APIs.

var BGMainJPG = mustDecodeBG(``)

var RefUI720JPG = mustDecodeBG(``)

func mustDecodeBG(s string) []byte {
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		panic("assets: " + err.Error())
	}
	return b
}
